{"sql":"
CREATE TABLE employees.employee_projects (
    project_id SERIAL PRIMARY KEY,
    project_name VARCHAR(100) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    budget DECIMAL(10,2),
    status VARCHAR(20) DEFAULT 'active'
);

CREATE TABLE employees.project_assignments (
    assignment_id SERIAL PRIMARY KEY,
    employee_id BIGINT NOT NULL,
    project_id INTEGER NOT NULL,
    role VARCHAR(50) NOT NULL,
    allocation_percentage INTEGER CHECK (allocation_percentage BETWEEN 1 AND 100),
    assigned_date DATE NOT NULL
);

CREATE TABLE employees.project_milestones (
    milestone_id SERIAL PRIMARY KEY,
    project_id INTEGER NOT NULL,
    milestone_name VARCHAR(100) NOT NULL,
    due_date DATE NOT NULL,
    completed BOOLEAN DEFAULT FALSE
);

ALTER TABLE employees.project_assignments ADD CONSTRAINT fk_assign_emp FOREIGN KEY (employee_id) REFERENCES employees.employee(id);
ALTER TABLE employees.project_assignments ADD CONSTRAINT fk_assign_proj FOREIGN KEY (project_id) REFERENCES employees.employee_projects(project_id);
ALTER TABLE employees.project_milestones ADD CONSTRAINT fk_milestone_proj FOREIGN KEY (project_id) REFERENCES employees.employee_projects(project_id);

CREATE INDEX idx_projects_status ON employees.employee_projects (status);
CREATE INDEX idx_assignments_emp_proj ON employees.project_assignments (employee_id, project_id);
CREATE INDEX idx_milestones_due_date ON employees.project_milestones (due_date);

